      "prompt": "Trong sinh hoạt hằng ngày, chất giặt rửa được sử dụng cùng với nước để loại bỏ các vết bẩn như dầu mỡ bám trên bề mặt rắn. Dựa vào nguồn gốc và thành phần, chất giặt rửa được chia thành xà phòng và chất giặt rửa tổng hợp. Xà phòng là muối sodium hoặc potassium của các acid béo, còn chất giặt rửa tổng hợp thường là muối sodium của alkyl sulfate hoặc alkylbenzenesulfonate. Cả hai loại đều có tính hoạt động bề mặt do phân tử gồm một phần kị nước dễ tương tác với dầu mỡ và một phần ưa nước có khả năng tan trong nước. Khi giặt rửa, các phân tử này giúp phân tán vết bẩn thành những hạt nhỏ và cuốn trôi theo nước.\n⟦1-5-f1⟧\nCho các phát biểu sau:\n(a) Dùng xà phòng khi giặt rửa với nước cứng sẽ tạo ra kết tủa \\(\\mathrm{CaCO_{3}}\\), \\(\\mathrm{MgCO_{3}}\\) làm giảm tác dụng giặt rửa.\n(b) Xà phòng và chất giặt rửa tổng hợp có tác dụng làm giảm sức căng bề mặt của dung dịch, từ đó giúp loại bỏ các vết bẩn dầu mỡ dễ dàng hơn.\n(c) Xà phòng và chất giặt rửa tổng hợp đều được sản xuất bằng cách đun nóng chất béo với dung dịch kiềm.\n(d) Trong quá trình giặt rửa, đầu ưa nước trong xà phòng và chất giặt rửa thâm nhập vào vết bẩn.\nSố phát biểu không đúng là",
