      "explanation": "\\(\\mathrm{CH_{3}COOC_{2}H_{5}} + \\mathrm{NaOH} \\to \\mathrm{CH_{3}COONa} + \\mathrm{C_{2}H_{5}OH}\\)\n\\(n_{\\mathrm{CH_{3}COOC_{2}H_{5}}} = 0{,}1\\); \\(n_{\\mathrm{NaOH}} = 0{,}15\\)\n\\(\\to\\) Chất rắn gồm \\(\\mathrm{CH_{3}COONa}\\) (0,1) và \\(\\mathrm{NaOH}\\) dư (0,05)\n\\(\\to\\) m rắn = 10,2 gam"
