      "answerText": "\\(7{,}5\\)",
      "prompt": "Nhà máy T sử dụng mỡ động vật để sản xuất bánh xà phòng. Trong một loại mỡ lợn X có chứa \\(44{,}5\\%\\) khối lượng tristearin; \\(44{,}2\\%\\) khối lượng triolein; \\(8{,}06\\%\\) khối lượng tripalmitin và \\(3{,}24\\%\\) tạp chất trơ. Dưới đây là bảng giá nguyên liệu và các chi phí:\n⟦1-27-t1⟧\nBiết hiệu suất phản ứng xà phòng hóa là \\(80\\%\\); tất cả các muối sinh ra từ phản ứng đều dùng làm xà phòng; khối lượng muối của acid béo trong xà phòng thành phẩm chiếm \\(75\\%\\) về khối lượng còn lại là phụ gia và chất độn; mỗi bánh có khối lượng tịnh là 90 gam (khối lượng tịnh là khối lượng của một vật thể nhưng không tính bao bì kèm theo); X tác dụng với dung dịch \\(\\mathrm{NaOH}\\) (vừa đủ). Giá tiền của 1 bánh xà phòng mà nhà máy trên sản xuất ra là a nghìn VNĐ. Giá trị của a là bao nhiêu? (Chỉ làm tròn ở phép tính cuối cùng, làm tròn kết quả đến chữ số hàng phần chục)",
      "explanation": "\\(n(\\mathrm{C_{17}H_{35}COO})\\) ₃C₃H₅ : \\(n(\\mathrm{C_{15}H_{31}COO})\\) ₃C₃H₅ : \\(n(\\mathrm{C_{17}H_{33}COO})\\) ₃C₃H₅) = 44,5/890 : 8,06/806 : 44,2/\\(884 = 0{,}05 : 0{,}01 : 0{,}05 = 5 : 1 : 5\\)\nTự chọn \\(\\mathrm{(C_{17}H_{35}COO)_{3}C_{3}H_{5}}\\) (\\(5\\,\\mathrm{mol}\\)); \\(\\mathrm{(C_{15}H_{31}COO)_{3}C_{3}H_{5}}\\) (\\(1\\,\\mathrm{mol}\\)); \\(\\mathrm{(C_{17}H_{33}COO)_{3}C_{3}H_{5}}\\)) (\\(5\\,\\mathrm{mol}\\))\n\\(\\to\\) m mỡ = 890.5/\\(44{,}5\\% = 10000\\) gam = \\(10\\,\\mathrm{kg}\\)\n\\(\\to\\) Chi phí mục (1) = 10.\\(30 = 300\\) (nghìn đồng)\n\\(n_{\\mathrm{NaOH}} = 3 \\cdot 80\\%\\).(\\(5 + 1 + 5\\)) = \\(26{,}4\\,\\mathrm{mol}\\)\n\\(\\to\\) mddNaOH = 26,4.40/\\(40\\% = 2640\\) gam = \\(2{,}64\\,\\mathrm{kg}\\)\n\\(\\to\\) Chi phí mục (2) = 2,64.\\(19 = 50{,}16\\) (nghìn đồng)\nm muối = \\(80\\%\\)(15.\\(306 + 3 \\cdot 278 + 15 \\cdot 304\\)) = 7987,2 gam = \\(7{,}9872\\,\\mathrm{kg}\\)\nMuối chiếm \\(75\\%\\) nên phụ gia và chất độn chiếm \\(25\\% \\cdot m\\) phụ gia và chất độn = 7,9872/\\(3 = 2{,}6624\\,\\mathrm{kg}\\)\n\\(\\to\\) Chi phí mục (3) = 2,6624.\\(100 = 266{,}24\\) (nghìn đồng)\nm thành phẩm = 7,9872/\\(75\\% = 10{,}6496\\,\\mathrm{kg}\\)\nĐổi: 2.500 đ/100 gam = 25000/\\(1\\,\\mathrm{kg}\\)\n\\(\\to\\) Chi phí mục (4) = 10,6496.\\(25 = 266{,}24\\) (nghìn đồng)\nTổng chi phí = 882,64 (nghìn đồng)\nSố bánh xà phòng = 10,6496.1000/\\(90 = 118{,}329\\) bánh\nChi phí cho mỗi bánh = 882,64/\\(118{,}329 = 7{,}46\\) (nghìn đồng)",
