      "answerText": "\\(6\\)",
      "prompt": "Alcohol X (\\(M_{\\mathrm{X}} = 76\\)) tác dụng với carboxylic acid Y thu được hợp chất Z mạch hở (X và Y đều chỉ có một loại nhóm chức). Phân tích Z thu được kết quả %\\(C = 48{,}84\\%\\); %\\(H = 4{,}65\\%\\) và %\\(\\mathrm{O} = 46{,}51\\%\\). Mặt khác, 17,2 gam Z lại phản ứng vừa đủ với 8 gam \\(\\mathrm{NaOH}\\) trong dung dịch. Biết Z có công thức phân tử trùng với công thức đơn giản nhất. Tổng số CTCT của X, Y, Z thỏa mãn là bao nhiêu?",
      "explanation": "\\(M_{\\mathrm{X}} = 76\\) \\(\\longrightarrow\\) X là \\(\\mathrm{C_{3}H_{6}(OH)_{2}}\\)\nX có 2 cấu tạo: \\(\\mathrm{CH_{3}{-}CHOH{-}CH_{2}OH}\\) và \\(\\mathrm{CH_{2}(CH_{2}OH)_{2}} \\cdot C : H : \\mathrm{O} = 48{,}84 / 12 : 4{,}65 / 1 : 46{,}51 / 16\\)\n= 4,07 : 4,65 : \\(2{,}91 = 1{,}4 : 1{,}6 : 1 = 7 : 8 : 5\\)\nZ là \\(\\mathrm{C_{7}H_{8}O_{5}}\\)\nnZ = 0,1; \\(n_{\\mathrm{NaOH}} = 0{,}2\\) \\(\\longrightarrow\\) nZ : \\(n_{\\mathrm{NaOH}} = 1 : 2\\) \\(\\longrightarrow\\) Z có \\(2\\mathrm{COO}\\) (ester hoặc cả acid)\nZ có 5 nguyên tử O nên Z còn 1 nhóm alcohol. Z có 3 cấu tạo:\n\\(\\mathrm{CH_{3}{-}CHOH{-}CH_{2}{-}OOC{-}C\\equiv C{-}COOH}\\)\n\\(\\mathrm{HOCH_{2}{-}CH(CH_{3}){-}OOC{-}C\\equiv C{-}COOH}\\)\n\\(\\mathrm{HOCH_{2}{-}CH_{2}{-}CH_{2}{-}OOC{-}C\\equiv C{-}COOH}\\)\nY có 1 cấu tạo: \\(\\mathrm{HOOC{-}C\\equiv C{-}COOH}\\)\nTổng số CTCT của X, Y, Z thỏa mãn là 6."
