      "prompt": "Một nhóm học sinh tiến hành thí nghiệm thủy phân hoàn toàn tinh bột để điều chế glucose, sau đó thử tính chất của glucose bằng thuốc thử Fehling. Thuốc thử Fehling là một dung dịch hóa học được sử dụng phổ biến trong các thí nghiệm phân tích hữu cơ để nhận biết đường khử. Phản ứng Fehling cho phép phát hiện các hợp chất khử như glucose thông qua quá trình oxi hóa-khử. Đây là công cụ quan trọng trong hóa học phân tích để kiểm tra tính khử của các chất hữu cơ. Do quá trình xảy ra các hiện tượng không thể quan sát được nên để biết tiến trình của phản ứng thủy phân có thể sử dụng thêm iodine làm chất nhận biết. Các bước trong thí nghiệm này như sau:\n(1) Sau khoảng 20 phút, hút lấy 1 – 2 giọt dung dịch trong ống nghiệm (a) nhỏ vào ống nghiệm (b) để kiểm tra tiến trình thủy phân.\n(2) Cho vào ống nghiệm (a) dung dịch hồ tinh bột \\(2\\%\\) và dung dịch \\(\\mathrm{H_{2}SO_{4}}\\) \\(10\\%\\) lắc đều rồi đặt ống nghiệm trong nồi nước sôi. Cho vào ống nghiệm (b) dung dịch \\(\\mathrm{I_{2}}\\) trong \\(\\mathrm{KI}\\).\n(3) Thêm tiếp vào ống nghiệm (c) vài giọt dung dịch \\(\\mathrm{CuSO_{4}}\\) \\(5\\%\\), lắc đều rồi đun nóng ống nghiệm.\n(4) Lấy khoảng \\(1\\,\\mathrm{mL}\\) dung dịch đã thủy phân hoàn toàn sang ống nghiệm (c), thêm dần từng giọt dung dịch \\(\\mathrm{NaOH}\\) \\(10\\%\\) cho đến môi trường kiềm.\nHãy sắp xếp số thứ tự các bước theo trình tự thành dãy bốn số để thực hiện thí nghiệm ở trên (Câu: 1234,4213, …).",
