      "value": 3289,
      "answerText": "\\(3289\\)",
      "prompt": "Xăng E5 (xăng sinh học) bán ngoài thị trường là xăng có \\(5\\%\\) ethanol theo thể tích. Một nhà máy sản xuất ethanol để pha xăng E5 (xăng sinh học) dùng nguyên liệu\nlà hạt ngô khô để lên men rượu theo sơ đồ sau : \\(\\mathrm{(C_{6}H_{10}O_{5})_{n}}\\) \\(\\xrightarrow{55\\%}\\) \\(\\mathrm{C_{6}H_{12}O_{6}}\\) \\(\\xrightarrow{65\\%}\\) \\(\\mathrm{C_{2}H_{5}OH}\\). Cho biết trong hạt ngô khô có \\(64{,}8\\%\\) khối lượng tinh bột, ethanol có khối lượng riêng là \\(0{,}8\\,\\mathrm{g}\\)/mL\nNếu dùng 1 tấn hạt ngô khô thì ethanol thu được có thể được bao nhiêu lít pha xăng E5. (Kết quả làm tròn đến hàng đơn vị).",
      "explanation": "\\(\\mathrm{(C_{6}H_{10}O_{5})_{n}}\\) \\(\\xrightarrow{35{,}75\\%}\\) \\(2\\mathrm{C_{2}H_{5}OH}\\).\n\\[\\begin{array}{rr}162 & 92\\\\648000\\,\\mathrm{g} & x\\end{array}\\]\n\\(\\Rightarrow\\) \\(x\\) = \\(\\dfrac{648000\\cdot92\\cdot35{,}75}{162\\cdot100}\\)= 131560 gam\n\\(\\Rightarrow\\) \\(V_{\\mathrm{R}}\\) = \\(\\dfrac{131560}{0{,}8}\\) = \\(164450\\,\\mathrm{mL} = 164{,}45\\,\\mathrm{L}\\)\n\\(\\Rightarrow\\) \\(V_{\\mathrm{R}} = 5\\%\\)VE₅ \\(\\Rightarrow\\) VE₅= V/\\(5\\%\\) = \\(\\dfrac{164{,}45\\cdot100}{5}\\)=\\(3289\\,\\mathrm{L}\\)"
