      "value": 389,
      "answerText": "\\(389\\)",
      "prompt": "Trong y học, dung dịch glucose \\(5\\%\\) (G-5) là dịch truyền tĩnh mạch cho những trường hợp bệnh nhân thiếu nước và năng lượng theo chỉ định của bác sĩ.\nDịch truyền G-5 có chứa 5 gam glucose trong \\(100\\,\\mathrm{mL}\\) dung dịch, đây là cách biểu thị nồng độ khối lượng theo thể tích, rất phổ biến trong y khoa.\nGiả thiết trong cơ thể, glucose bị oxi hoá giải phóng năng lượng theo PTHH:\n\\(\\mathrm{C_6H_{12}O_6(aq)+6O_2(g)}\\xrightarrow[37\\,{}^\\circ\\mathrm C]{\\text{enzyme}}\\mathrm{6CO_2(g)+6H_2O(l)}\\)\nCho nhiệt tạo thành của các chất ở điều kiện phản ứng bằng nhiệt tạo thành chuẩn:\n⟦2-13-t40⟧\nMột chai chứa \\(500\\,\\mathrm{mL}\\) dịch truyền G-5 cung cấp được tối đa a kJ năng lượng từ glucose. Giá trị của a bằng bao nhiêu? (kết quả làm tròn đến hàng đơn vị).",
      "explanation": "Đáp án: 389\n100 mL dung dịch có 5 gam glucose \\(\\Rightarrow\\) 500 mL dung dịch có 25 gam glucose\n\\[\\begin{aligned}\\Rightarrow n_{\\text{glucose}}&=\\frac{25}{180}=\\frac{5}{36}\\,\\mathrm{mol}\\\\ \\Delta_{\\mathrm r}H^\\circ_{298}&=6(-393{,}5)+6(-285{,}8)-(-1273{,}3)=-2802{,}5\\,\\mathrm{kJ}\\\\ \\Rightarrow a&=\\frac{5}{36}\\cdot2802{,}5\\simeq389\\end{aligned}\\]",
