      "prompt": "(Đúng/sai) Trong phân tích hàm lượng protein của mẫu ngũ cốc bằng phương pháp Kjeldahl, tiến hành các bước sau:\n• Phân hủy mẫu: Cân \\(1{,}3725\\,\\mathrm{g}\\) bột ngũ cốc, cho vào bình cầu chứa \\(18\\,\\mathrm{mL}\\) \\(\\mathrm{H_{2}SO_{4}}\\) đặc, thêm xúc tác và đun sôi trong 2,5 giờ. Giả sử toàn bộ nitrogen trong protein được chuyển thành \\(\\mathrm{NH_{4}^{+}}\\).\n• Giải phóng và thu \\(\\mathrm{NH_{3}}\\): Sau khi làm nguội, thêm \\(250\\,\\mathrm{mL}\\) nước, \\(30{,}0\\,\\mathrm{g}\\) \\(\\mathrm{NaOH}\\), chưng cất và dẫn khí \\(\\mathrm{NH_{3}}\\) vào \\(60{,}0\\,\\mathrm{mL}\\) dung dịch \\(\\mathrm{HCl}\\) \\(0{,}0825\\,\\mathrm{M}\\).\n• Chuẩn độ: Chuẩn độ lượng acid dư bằng \\(\\mathrm{NaOH}\\) \\(0{,}0610\\,\\mathrm{M}\\), dùng chỉ thị methyl red; thể tích \\(\\mathrm{NaOH}\\) tiêu tốn là \\(41{,}20\\,\\mathrm{mL}\\).\nBiết hàm lượng nitrogen trong protein của ngũ cốc là \\(16{,}80\\%\\), xác định phần trăm khối lượng protein trong mẫu là ℎ%.",
      "explanation": "a. Sai.\nb. Đúng.\nc. Sai vì khoá kiểm soát \\(\\mathrm{HCl}\\) vừa đủ và thất thoát \\(\\mathrm{NH_{3}}\\) bay ra.\nd. Đúng.\n\\[n_{\\mathrm{HCl},\\,\\text{ban đầu}}=0{,}0825\\times0{,}0600=4{,}95\\times10^{-3}\\,\\mathrm{mol}\\]\n\\[n_{\\mathrm{NaOH}}=0{,}0610\\times0{,}04120=2{,}5132\\times10^{-3}\\,\\mathrm{mol}\\]\n\\[n_{\\mathrm{HCl}\\,\\text{dư}}=2{,}5132\\times10^{-3}\\,\\mathrm{mol}\\]\n\\[n_{\\mathrm{HCl}\\,\\text{phản ứng}}=4{,}95\\times10^{-3}-2{,}5132\\times10^{-3}=2{,}4368\\times10^{-3}\\,\\mathrm{mol}\\]\n\\[n_{\\mathrm{NH_3}}=2{,}4368\\times10^{-3}\\,\\mathrm{mol}\\]\n\\[n_{\\mathrm N}=2{,}4368\\times10^{-3}\\,\\mathrm{mol}\\]\n\\[m_{\\mathrm N}=0{,}0024368\\times14=0{,}0341152\\,\\mathrm g\\]\n\\[m_{\\mathrm{protein}}=\\frac{0{,}0341152}{0{,}168}=\\frac{1523}{7500}\\,\\mathrm g\\]\n\\[h=\\frac{\\frac{1523}{7500}}{1{,}3725}\\times100=14{,}8\\%.\\]"
