      "prompt": "Polymer là các hợp chất cao phân tử có vai trò quan trọng trong cuộc sống và công nghiệp. Tuỳ theo thành phần và cấu trúc mà polymer có thể có tính dẻo, tính đàn hồi,... Dựa vào sự biến đổi khác nhau khi bị đun nóng, polymer có thể được chia thành polymer nhiệt dẻo và polymer nhiệt rắn.\n1) Hầu hết polymer tan được trong nước và có nhiệt độ nóng chảy xác định.\n2) Tính chất vật lí của polymer phụ thuộc vào cấu tạo.\n3) PE và \\(\\mathrm{PVC}\\) là các polymer có tính dẻo và thuộc loại polymer nhiệt dẻo.\n4) Cellulose là polymer có cấu trúc mạch phân nhánh.\n5) Tơ nylon-6,6 thuộc loại tơ polyamide nên bền trong môi trường kiềm\n6) Cao su lưu hóa có tính đàn hồi, chịu nhiệt tốt hơn cao su không lưu hóa\nLiệt kê đáp án theo dãy số thứ tự tăng dần (ví dụ: 1234,235,…).",
