      "answerText": "\\(20\\)",
      "prompt": "Cân 5,00 gam mẫu quặng Manhetite, hòa tan hoàn toàn bằng dung dịch \\(\\mathrm{HCl}\\) đặc, nóng trong điều kiện không có oxygen (sục khí \\(\\mathrm{N_{2}}\\) liên tục) thu được dung dịch X. Để nguội, thêm nước cất đến vạch định mức để thu được \\(250\\,\\mathrm{mL}\\) dung dịch X.\nLấy \\(25{,}0\\,\\mathrm{mL}\\) dung dịch X, thêm hỗn hợp \\(\\mathrm{H_{2}SO_{4}} / \\mathrm{H_{3}PO_{4}}\\) và chỉ thị diphenylamine\nsulfonate. Tiến hành chuẩn độ \\(\\mathrm{Fe^{2+}}\\) bằng dung dịch chuẩn \\(\\mathrm{K_{2}Cr_{2}O_{7}}\\) \\(0{,}02\\,\\mathrm{M}\\), thể tích tiêu tốn là \\(8{,}0\\,\\mathrm{mL}\\).\nLấy \\(25{,}0\\,\\mathrm{mL}\\) dung dịch X, thêm dung dịch \\(\\mathrm{SnCl_{2}}\\) dư để khử toàn bộ \\(\\mathrm{Fe^{3+}}\\) thành \\(\\mathrm{Fe^{2+}}\\). Loại bỏ \\(\\mathrm{SnCl_{2}}\\) dư bằng \\(\\mathrm{HgCl_{2}}\\), sau đó chuẩn độ bằng dung dịch chuẩn \\(\\mathrm{K_{2}Cr_{2}O_{7}}\\) 0,\\(02\\,\\mathrm{M}\\) thì thấy hết \\(30{,}0\\,\\mathrm{mL}\\).\nPhản ứng chuẩn độ được cho như sau: \\(6\\mathrm{Fe^{2+}}\\) + \\(\\mathrm{Cr_2O_7^{2-}}\\)+ \\(14\\mathrm{H^{+}} \\to 6\\mathrm{Fe^{3+}} + 2\\mathrm{Cr^{3+}} + 7\\mathrm{H_{2}O}\\)\nGiả sử mẫu quặng ban đầu chỉ gồm \\(\\mathrm{Fe_{3}O_{4}}\\) và tạp chất trơ, hãy tính phần trăm \\(\\mathrm{Fe_{3}O_{4}}\\) đã bị chuyển hóa thành \\(\\mathrm{Fe_{2}O_{3}}\\) do quá trình phong hóa (Kết quả làm tròn đến hàng đơn vị).",
      "explanation": "\\(6\\mathrm{Fe^{2+}}\\) + \\(\\mathrm{Cr_2O_7^{2-}}\\)+ \\(14\\mathrm{H^{+}} \\to 6\\mathrm{Fe^{3+}} + 2\\mathrm{Cr^{3+}} + 7\\mathrm{H_{2}O}\\)\nTrong \\(25\\,\\mathrm{mL}\\)\n\\(n_{\\mathrm{Fe^{2+}}}\\)= \\(6 \\times 0{,}02 \\times 0{,}008 = 9{,}6 \\times 10^{-4}\\,\\mathrm{mol}\\)\n\\(n_{\\mathrm{Fe\\,(tổng)}}\\)= \\(6 \\times 0{,}02 \\times 0{,}030 = 3{,}6 \\times 10^{-3}\\,\\mathrm{mol}\\)\n\\(n_{\\mathrm{Fe^{3+}}}\\)= \\(3{,}6 \\times 10^{-3} - 9{,}6 \\times 10^{-4} = 2{,}64 \\times 10^{-3}\\,\\mathrm{mol}\\) Trong \\(\\mathrm{Fe_{3}O_{4}}\\) lý thuyết, \\(\\mathrm{Fe^{2+}}\\) chiếm 1/3 tổng lượng \\(\\mathrm{Fe}\\)\nLượng \\(\\mathrm{Fe^{2+}}\\) đáng lẽ phải có: (\\(3{,}6 \\times 10^{-3}\\) )/\\(3 = 1{,}2 \\times 10^{-3}\\,\\mathrm{mol}\\)\nLượng \\(\\mathrm{Fe^{2+}}\\) thực tế bị mất do quá trình oxy hóa: \\(1{,}2 \\times 10^{-3} - 9{,}6 \\times 10^{-4} = 2{,}4 \\times 10^{-4}\\,\\mathrm{mol}\\)\n\\(\\frac{2{,}4\\times10^{-3}\\times100\\%}{1{,}2\\times10^{-3}}\\)\nPhần trăm \\(\\mathrm{Fe_{3}O_{4}}\\) đã bị phong hóa là = \\(20\\%\\)"
