      "prompt": "Khi hòa tan tinh thể \\(\\mathrm{CoCl_{2}} \\cdot 6\\mathrm{H_{2}O}\\) vào nước, ion \\(\\mathrm{Co^{2+}}\\) tạo thành phức chất\n\\(\\mathrm{[Co(OH_{2})_{6}]^{2+}}\\) có màu hồng. Trong dung dịch có mặt ion \\(\\mathrm{Cl^{-}}\\), phức chất này có thể\nchuyển hóa thành \\(\\mathrm{[CoCl_{4}]^{2-}}\\) có màu xanh lam. Hai phức chất tồn tại trong một hệ cân bằng được mô tả bằng phương trình sau:\n\\(\\underset{\\text{hồng}}{\\mathrm{[Co(OH_2)_6]^{2+}(aq)}}+\\mathrm{4Cl^-(aq)}\\underset{(2)}{\\overset{(1)}{\\rightleftharpoons}}\\underset{\\text{xanh lam}}{\\mathrm{[CoCl_4]^{2-}(aq)}}+\\mathrm{6H_2O(l)}\\)\nĐể tìm hiểu tác động của các yếu tố như nhiệt độ và nồng độ ion \\(\\mathrm{Cl^{-}}\\) đến chuyển dịch cân bằng của phản ứng trên, một nhóm học sinh đã tiến hành ba thí nghiệm như sau:\n- Thí nghiệm 1: Đun sôi dung dịch có màu hồng, thấy dung dịch chuyển màu từ hồng sang xanh lam.\n- Thí nghiệm 2: Thêm dung dịch \\(\\mathrm{AgNO_{3}}\\) vào dung dịch xanh lam, đun nóng, thấy xuất hiện kết tủa trắng \\(\\mathrm{AgCl}\\), đồng thời dung dịch chuyển sang màu hồng.\n- Thí nghiệm 3: Nhỏ từ từ dung dịch \\(\\mathrm{HCl}\\) vào dung dịch màu hồng ở nhiệt độ phòng, thấy dung dịch đổi từ màu hồng sang màu xanh lam.\nCó bao nhiêu phát biểu đúng trong số các phát biểu sau:\n(1) Ở thí nghiệm 1, quan sát thấy dung dịch đổi từ màu hồng sang màu xanh khi đun nóng chứng tỏ phản ứng theo chiều (1) là phản ứng toả nhiệt.\n(2) Pha loãng dung dịch màu xanh chứa \\(\\mathrm{[CoCl_{4}]^{2-}}\\) bằng nước cất làm cân bằng không chuyển dịch vì nồng độ các chất đều giảm.\n(3) Ở thí nghiệm 3, do nồng độ \\(\\mathrm{Cl^{-}}\\) tăng khi thêm dung dịch \\(\\mathrm{HCl}\\) ở nhiệt độ phòng làm cân bằng chuyển dịch theo chiều (2), khiến dung dịch chuyển sang màu xanh lam.\n(4) Ở thí nghiệm 2, khi thêm \\(\\mathrm{AgNO_{3}}\\) vào, ion \\(\\mathrm{Ag^{+}}\\) phản ứng với \\(\\mathrm{Cl^{-}}\\) tạo kết tủa trắng \\(\\mathrm{AgCl}\\). Sự giảm nồng độ \\(\\mathrm{Cl^{-}}\\) khiến dung dịch chuyển từ màu xanh lam sang màu hồng.",
